function storyText(s){return esc(s.replaceAll('{hero}',state.hero).replaceAll('{partner}',state.partner))}
function render(){const node=state.nodes[state.current];$('#app').innerHTML=`<div class="grid"><div>${panel(node.ending?'你的选择，写下了结局':node.title,`<span class="tag">${state.theme} / ${state.path.length+1} 幕</span><p class="quote" style="margin-top:24px">${storyText(node.text)}</p>${node.ending?`<div class="result">${storyText(node.lesson)}</div><button id="restart" class="primary" style="margin-top:20px">重新开拍，探索另一个结局</button>`:node.choices.map((x,i)=>`<button class="choice" data-action="${i}">${storyText(x.label)}</button>`).join('')}`)}${panel('导演的选择记录',state.path.map((x,i)=>`<div class="item"><span>第 ${i+1} 幕</span><strong>${storyText(x)}</strong></div>`).join('')||empty('还没有选择。故事在等你。'))}</div><div>${panel('角色设定室',`<form id="cast" class="stack">${field('主角代号','hero','text',state.hero,'required maxlength="20"')}${field('伙伴代号','partner','text',state.partner,'required maxlength="20"')}${select('故事呈现主题','theme',['森林奇遇','星际舞台','海底剧场'],state.theme)}<p class="notice">角色约束：主角不使用暴力；伙伴不能独自离开。分支遵守这些规则。主题改变展示标签，情节结构保持可比较。</p><button>保存角色设定</button></form>`)}${panel('结局收藏册',`<h2>${new Set(state.endings).size} / ${Object.values(state.nodes).filter(x=>x.ending).length} 个结局</h2>${Object.keys(state.nodes).filter(x=>state.nodes[x].ending).map(x=>`<p>${state.endings.includes(x)?'✦':'○'} ${state.endings.includes(x)?esc(state.nodes[x].title):'尚未发现的结局'}</p>`).join('')}`,'tint')}${panel('改写当前镜头',`<form id="rewrite" class="stack"><label>当前情节<textarea name="text" required maxlength="800">${esc(node.text)}</textarea></label><p class="notice">保留 {hero}、{partner} 可随角色名更新。文字改写不会自动生成新分支；新增分支可修改 data/seed.js。</p><button>保存我的改写</button></form>`)}</div></div>`;
actions('[data-action]',i=>{const c=node.choices[+i];state.path.push(c.label);state.current=c.next;if(state.nodes[state.current].ending&&!state.endings.includes(state.current))state.endings.push(state.current);commit()});on('restart',()=>{state.current='start';state.path=[];commit()});form('cast',v=>{Object.assign(state,v);commit();toast('角色设定已更新')});form('rewrite',v=>{node.text=v.text;commit();toast('当前镜头已改写')})}render();
